using Microsoft.EntityFrameworkCore; using VietVan.API.Data; using VietVan.API.DTOs.Works; using VietVan.API.Entities; using VietVan.API.Services.Interfaces;
namespace VietVan.API.Services.Implementations;
public class WorkService(VietVanDbContext db):IWorkService { public async Task<PagedResponse<WorkListItem>> GetPublicAsync(int page,int pageSize,string? search){page=Math.Max(page,1);pageSize=Math.Clamp(pageSize,1,100);var q=db.LiteraryWorks.AsNoTracking().Where(x=>x.IsActive);if(!string.IsNullOrWhiteSpace(search)){var s=search.Trim();q=q.Where(x=>x.Title.Contains(s)||x.Author.Contains(s));}var total=await q.CountAsync();var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((int)Math.Min((long)(page-1)*pageSize,int.MaxValue)).Take(pageSize).Select(x=>new WorkListItem(x.Id,x.Title,x.Author,x.Description,x.CoverImageUrl,x.RequiredTierLevel)).ToListAsync();return new(items,page,pageSize,total,(int)Math.Ceiling(total/(double)pageSize));}
public async Task<LiteraryWork> CreateAsync(CreateWorkRequest r){var w=new LiteraryWork{Title=r.Title.Trim(),Author=r.Author.Trim(),Description=r.Description,Content="",CoverImageUrl=r.CoverImageUrl,RequiredTierLevel=r.RequiredTierLevel,IsActive=r.IsActive,CreatedAt=DateTime.UtcNow};db.Add(w);await db.SaveChangesAsync();return w;}public async Task<LiteraryWork> ToggleAsync(int id){var w=await db.LiteraryWorks.FindAsync(id)??throw new KeyNotFoundException("Không tìm thấy tác phẩm.");w.IsActive=!w.IsActive;w.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return w;}}
